    """
    Check if the given number is undulating, meaning the digits strictly alternate between increasing and decreasing.

    Args:
    n (int): The number to check.

    Returns:
    bool: True if the number is undulating, False otherwise.
    """
    if n < 10:
        return False  # Single-digit numbers cannot be undulating

    s = str(n)
    length = len(s)

    # The number must have at least two digits to be undulating
    if length < 2:
        return False

    # Determine the direction of the first change
    direction = None

    for i in range(length - 1):
        if s[i] > s[i+1]:
            current_direction = -1
        elif s[i] < s[i+1]:
            current_direction = 1
        else:
            return False  # Consecutive digits are equal

        if direction is None:
            direction = current_direction
        else:
            if current_direction == direction:
                return False  # Direction must alternate

    return True
