def is_majority(arr, n, x):
    if n == 0:
        return False

    # Since the array is sorted, we can use binary search to find the first and last occurrences of x
    def find_first(arr, x):
        left, right = 0, n - 1
        first = -1
        while left <= right:
            mid = (left + right) // 2
            if arr[mid] == x:
                first = mid
                right = mid - 1
            elif arr[mid] < x:
                left = mid + 1
            else:
                right = mid - 1
        return first

    def find_last(arr, x):
        left, right = 0, n - 1
        last = -1
        while left <= right:
            mid = (left + right) // 2
            if arr[mid] == x:
                last = mid
                left = mid + 1
            elif arr[mid] < x:
                left = mid + 1
            else:
                right = mid - 1
        return last

    first_occurrence = find_first(arr, x)
    last_occurrence = find_last(arr, x)

    if first_occurrence == -1 or last_occurrence == -1:
        return False

    count = last_occurrence - first_occurrence + 1
    return count > n // 2
