def is_majority(arr, n, x):
    # Find the first and last occurrence of x in the sorted array
    left = 0
    right = n - 1
    first = -1
    last = -1

    # Binary search to find the first occurrence of x
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == x:
            first = mid
            right = mid - 1
        elif arr[mid] < x:
            left = mid + 1
        else:
            right = mid - 1

    right = n - 1
    # Binary search to find the last occurrence of x
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == x:
            last = mid
            left = mid + 1
        elif arr[mid] < x:
            left = mid + 1
        else:
            right = mid - 1

    # Check if x is a majority element
    if first == -1:
        return False
    else:
        return (last - first + 1) > n // 2
