def reverse_Array_Upto_K(input, k):
    # Handle edge case where k is out of bounds (e.g., k > len(input) or k <= 0)
    if k <= 0 or k > len(input):
        return input.copy()

    # Slice the array up to k elements and reverse it
    reversed_slice = input[:k][::-1]
    # Combine the reversed slice with the remaining elements
    return reversed_slice + input[k:]
