def left_rotate(n, d):
    if d < 0:
        return n  # or handle negative d as per requirements, but problem assumes d is valid
    # Since we're working with 32-bit numbers, take modulo 32 to handle cases where d > 32
    d = d % 32
    # Left rotate by d bits: (n << d) | (n >> (32 - d))
    return (n << d) | (n >> (32 - d))
```

